INSERT INTO products ("id", "name", "category", "category_display", "tags", "price_display", "min_price", "max_price", "sale_badge", "inspired_by", "rating", "reviews_count", "image", "secondary_image", "description", "pyramid", "variants", "in_stock", "subcategory", "created_at", "updated_at") VALUES ('touch-oud', 'TOUCH OUD', 'oud', 'OUD', '["mens","oud","touch-oud","75ml"]'::jsonb, 'Rs8,500', '8500.00', '8500.00', NULL, NULL, '5.00', 33, 'https://res.cloudinary.com/oelbtnhb/image/upload/v1791473867/utoorateazami/products/touch-oud-primary.png', 'https://res.cloudinary.com/oelbtnhb/image/upload/v1791473868/utoorateazami/products/touch-oud-secondary.png', 'Besiege in with tickling perfusions of TOUCH OUD. Let go the scents beyond the Middle East. Just a trifling amount of splash, fills your essence with liveliness; as juicy citruses sums the top the note with their zesty flavors. Lavender’s resurgence to contemporary scents as a re-discoverable heart note in contrasts with vanilla’s spellbinding, delicious scent. Base accentuates the sophisticated scents of agarwood, which mingle with the smokey sensations of frankincense to form a complex and alluring fragrance. It’s a fascinating cascade of scents that elevates the cologne to a whole new extreme. Touch oud is embraced in 75ml EDP container.', '{}'::jsonb, '[{"size":"75ml","price":8500,"inStock":false,"regularPrice":8500}]'::jsonb, FALSE, NULL, '2026-10-08T15:37:48.284Z', '2026-10-08T15:37:48.284Z') ON CONFLICT (id) DO UPDATE SET updated_at = EXCLUDED.updated_at;
