INSERT INTO products ("id", "name", "category", "category_display", "tags", "price_display", "min_price", "max_price", "sale_badge", "inspired_by", "rating", "reviews_count", "image", "secondary_image", "description", "pyramid", "variants", "in_stock", "subcategory", "created_at", "updated_at") VALUES ('bakhoor-oud-roses', 'BAKHOOR OUD & ROSES', 'oud', 'OUD', '["oud","unisex","bakhoor-oud-roses","40g Bakhoor"]'::jsonb, 'Rs4,000', '4000.00', '4000.00', NULL, NULL, '5.00', 49, 'https://res.cloudinary.com/oelbtnhb/image/upload/v1791473875/utoorateazami/products/bakhoor-oud-roses-primary.png', '', 'Description Reviews (0) The fragrance of bakhoor oud and roses is delivered to you with the intention of illuminating your environs with a unique form of nature’s beauty. It is filled with the finest of divine roses. providing you with the most elegant aroma of oriental musky wood and linking the fragrance with a mixed bouquet of fresh natural blossoms of Turkish roses. The flavor is elevated by the sweet aroma of Indian roses, which brings it a more heavenly touch. The combination of white flowers, extremely rich, dense, and long-lasting oud extracts, a little smouldering pinch of guaiac wood, relaxing fragrance of sandalwood and lastly mixing to the scent infused with the richest and most valuable type of Amber absolute enable this sensuality to be revealed. Enrich your castle with the finest of Bakhoor tablets, which will cover it with the most exquisite aroma of beautiful flowers. Includes 10 tabs', '{}'::jsonb, '[{"size":"40g Bakhoor","price":4000,"inStock":false,"regularPrice":4000}]'::jsonb, FALSE, NULL, '2026-10-08T15:37:55.282Z', '2026-10-08T15:37:55.282Z') ON CONFLICT (id) DO UPDATE SET updated_at = EXCLUDED.updated_at;
